function isBalanced(s) {
  const stack = [];
  const pairs = { ")": "(", "]": "[", "}": "{" };
  for (const ch ___ s) {
    if (ch ___ "(" || ch === "[" || ch === "{") stack.___(ch);
    else if (stack.___() ___ pairs[ch]) return false;
  }
  return stack.length === 0;
}
console.log(isBalanced("([])"));

